import sys


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    edges = []
    for i in range(m):
        u = int(data[2 + 3 * i]); v = int(data[3 + 3 * i]); c = int(data[4 + 3 * i])
        edges.append((u, v, c))
    k = n - 2
    best = None
    for mask in range(1 << k):
        side = [False] * (n + 1)
        side[1] = True
        for i in range(k):
            if (mask >> i) & 1:
                side[i + 2] = True
        total = 0
        for u, v, c in edges:
            if side[u] != side[v]:
                total += c
        if best is None or total < best:
            best = total
    print(best)


main()
